// Zweck: Video-Text aus der Supadata-Antwort holen und pruefen (mode native liefert bei vorhandenen Untertiteln direkt Text).
const r = $input.first().json;
const body = r.body || {};
// Warum je Element pruefen (12.10.2026): null oder Zahlen in der Liste duerfen den Code nicht werfen lassen, sie fuehren ueber den Text-Check in F2.
const teil = t => (t && typeof t === 'object') ? String(t.text || '') : (typeof t === 'string' ? t : '');
let text = typeof body.content === 'string' ? body.content : (Array.isArray(body.content) ? body.content.map(teil).join(' ') : '');
text = text.split(String.fromCharCode(10)).join(' ').replace(/ {2,}/g, ' ').trim();
// Warum kein Abbruch: 202 mit jobId (Auftrag statt Text), 206 (keine Untertitel) und zu kurzer Text laufen in den Ausweichweg F2.
let grund = '';
if (r.statusCode === 202 || body.jobId) grund = 'Supadata lieferte einen Auftrag (202) statt Text';
else if (r.statusCode === 206) grund = 'keine Untertitel vorhanden (206)';
else if (text.length < 500) grund = 'Video-Text zu kurz oder leer (' + text.length + ' Zeichen)';
return [{ json: { video_text: grund ? '' : text, video_text_chars: text.length, language: body.lang || null, f2_reason: grund, status_code: r.statusCode } }];

// Zweck: Paket der KI pruefen und in Form bringen (Folienzahl, Laengen, Hashtags, Kennzeichnung).
const ein = $input.first().json;
const pModell = ein.output || (typeof ein.text === 'string' ? JSON.parse(ein.text) : ein.text) || {};
const basis = $('Quelltext vereinheitlichen [Edit Fields]').first().json;
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const kunde = basis.customer || {};
// Warum: F3, hat die Chain auf das Ersatzmodell umgeschaltet, steht das im Post und im Protokoll.
let ersatz = false;
try { ersatz = $('Ersatzmodell NVIDIA [NVIDIA Nemotron Chat Model]').isExecuted === true; } catch (e) { ersatz = false; }
// Warum aus dem Kostenknoten (v03): Tokens und Kosten erfasst der eigene Knoten direkt hinter dem HTTP-Aufruf, hier werden sie nur uebernommen.
const kost = $('Tokens und Kosten erfassen [Code]').first().json;
const vermerk = kost.cost_note ? [kost.cost_note] : [];
const tok = { prompt_tokens: kost.prompt_tokens, completion_tokens: kost.completion_tokens, total_tokens: kost.total_tokens, cost_usd: kost.cost_usd, token_source: kost.token_source };
// Warum nur ein Vermerk bei NVIDIA: der Ersatzweg laeuft durch dieselbe Kostenerfassung; NVIDIA Free Endpoint kostet 0, seine Tokens stehen nur im Modellknoten und sind im Code nicht lesbar.
if (ersatz) { vermerk.push('NVIDIA-Tokens nicht lesbar' + (kost.usage_present ? ', bekannt nur OpenRouter plus Sonar, Token-Summe im Protokoll bleibt leer' : '')); tok.token_source += ', nvidia ohne Tokenangabe'; }
const kuerze = (s, n) => { s = String(s || '').trim(); return s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s; };
// Warum Wortgrenze (19.10.2026, Lauf 1181): kuerze schnitt die Titelueberschrift (74 Zeichen) bei 69 Zeichen mitten im Wort, Folie 1 zeigte KLEINE F….
// Ueberschriften enden am letzten ganzen Wort vor der Grenze.
// Warum ohne Mindestlaenge: eine Wortgrenze vor der halben Grenze wurde verworfen, ein Mehrworttitel endete dann mitten im Wort
// (Kundenbindungsautomatisierungsplattform…). Jetzt wird immer an der letzten Wortgrenze gekuerzt, solange es eine gibt; nur ein einziges Wort ohne jede Grenze
// wird hart geteilt, das meldet ohneWortgrenze fuer einen eigenen Hinweis.
const ohneWortgrenze = (s, n) => { s = String(s || '').trim(); return s.length > n && !/\s/.test(s.slice(0, n)); };
const kuerzeWort = (s, n) => { s = String(s || '').trim(); if (s.length <= n) return s; let t = s.slice(0, n - 1); if (!/\s/.test(s[n - 1])) t = t.replace(/\s+\S*$/, ''); t = t.replace(/[\s,;:–—-]+$/, ''); return (t || s.slice(0, n - 1)) + '…'; };
// Schritte und Schrittzahl-Abgleich stehen vor den Folien, weil alle Texte den abgeglichenen Wortlaut brauchen.
// schritteRoh, ablaufThema und processSteps stehen jetzt hier (Wortlaut bis auf pModell unveraendert), weil der Schrittzahl-Abgleich sie vor allen Texten braucht.
const schritteRoh = (Array.isArray(pModell.process_steps) ? pModell.process_steps : []).map(s => String(s == null ? '' : s).trim()).filter(Boolean).slice(0, 5)
  .map(s => Array.from(s).length > 42 ? Array.from(s).slice(0, 41).join('').trimEnd() + '…' : s);
// Warum zusaetzlich das Thema (10.10.2026, Lauf 737): das Modell erfindet Schritte auch bei Themen ohne Ablauf. Die Ablauf-Folie kommt nur, wenn das Thema nach Ablauf oder Anleitung aussieht, sonst werden die Schritte verworfen.
const ablaufThema = /schritt|anleitung|so geht|so gehts|so funktioniert|ablauf|leitfaden|checkliste|tutorial|einrichten|wie du |wie man /i.test(String(basis.topic || ''));
const processSteps = ablaufThema && schritteRoh.length >= 3 ? schritteRoh : null;
// Warum Schrittzahl-Abgleich (19.10.2026, Lauf 1186): Titel und Aufhaenger sagten 4 Schritte, process_steps hatte 5, der LinkedIn-Text vier Schritten; Folie 1,
// LinkedIn-Bild (Abzeichen In 5 Schritten) und Post widersprachen sich. Steht in einer Folienueberschrift, im Aufhaenger, in der Einleitung, in der Instagram-Bildunterschrift
// oder im LinkedIn-Text eine Schrittzahl (Ziffer oder Zahlwort eins bis zehn, optional ein Adjektiv dazwischen wie einfachen, dann Schritt, Schritte, Schritten, Step, Steps)
// und weicht sie von der Zahl der gueltigen process_steps ab, wird sie auf diese Zahl gesetzt: Ziffer bleibt Ziffer, Zahlwort bleibt Zahlwort, Gross- und Kleinschreibung
// bleibt; Hinweis in quality_notes. Gueltig heisst: processSteps steht (Ablauf-Thema, 3 bis 5 Schritte), gezaehlt werden Schritte mit Buchstabe oder Ziffer (wie Render-Liste
// bauen). Ohne gueltige Schritte bleibt alles, wie es ist. Eine Teilmenge (die ersten, letzten, naechsten, weiteren, restlichen, beiden, uebrigen, folgenden 3 Schritte)
// bleibt stehen. Alle Pruefungen danach (Aufhaenger-Breite, Wiederholung, Zahlen) sehen den neuen Wortlaut. Das Modellobjekt selbst bleibt unveraendert (Kopie p).
const schrittAnzahl = processSteps ? processSteps.filter(s => /[\p{L}\p{N}]/u.test(String(s).replace(/\*/g, ''))).length : 0;
const SZ_WORT = ['', 'eins', 'zwei', 'drei', 'vier', 'fünf', 'sechs', 'sieben', 'acht', 'neun', 'zehn'];
const SZ_ZAHL = { eins: 1, zwei: 2, drei: 3, vier: 4, 'fünf': 5, fuenf: 5, sechs: 6, sieben: 7, acht: 8, neun: 9, zehn: 10 };
const SZ_MUSTER = /(^|[^\p{L}\p{N}])(\d{1,2}|eins|zwei|drei|vier|fünf|fuenf|sechs|sieben|acht|neun|zehn)((?:[\s-]+\p{L}+(?:en|e|er|es))?[\s-]+)(schritt(?:e|en)?|steps?)(?![\p{L}\p{N}])/giu;
const SZ_TEIL = /(?:^|[^\p{L}])(ersten|letzten|nächsten|naechsten|weiteren|restlichen|beiden|übrigen|uebrigen|folgenden)\s*$/iu;
const szFall = (alt, neu) => (alt === alt.toUpperCase() && alt !== alt.toLowerCase() ? neu.toUpperCase() : (alt[0] !== alt[0].toLowerCase() ? neu[0].toUpperCase() + neu.slice(1) : neu));
const szAlt = [], szOrte = [], szOffen = [];
// Warum nur kurze Felder (19.10.2026): ein frueherer Stand setzte die Schrittzahl auch im Fliesstext an Stellen, die eindeutig schienen, und schuetzte Vergleiche und
// Zitate mit Textheuristiken. Die Gegenprobe fand danach erneut 4 Faelle (die 4 Schritte fuer deinen Angebotsprozess blieb falsch, Frueher ging es in 10 Schritten wurde zu 5, einfache
// Anfuehrungszeichen und Zitate ueber Zeilen wurden veraendert). Jetzt gilt eine einfache Regel: korrigiert wird nur in kurzen Feldern (Titel, Aufhaenger, Folienueberschriften)
// und nur, wenn das Feld genau 1 Schrittzahl enthaelt, sie nicht in Anfuehrungszeichen steht (irgendein Anfuehrungszeichen davor und irgendeines danach, auch ueber Zeilen) und
// keine Teilmenge ist (die ersten 3 Schritte). Fliesstexte (Einleitung, Folientexte, Instagram, LinkedIn) werden nie geaendert. Jede abweichende Schrittzahl, die nicht
// korrigiert wird, steht als Hinweis in quality_notes: Schrittzahl im Text (N) weicht vom Ablauf (M) ab.
const SZ_ANF = /["'„“”‚‘’»«›‹]/;
const szWert = zahl => (/^\d+$/.test(zahl) ? parseInt(zahl, 10) : SZ_ZAHL[zahl.toLowerCase()]);
const szTreffer = s => Array.from(s.matchAll(SZ_MUSTER)).map(m => ({ zahl: m[2], start: m.index + m[1].length, wert: szWert(m[2]), teil: SZ_TEIL.test(s.slice(0, m.index + m[1].length)) }));
const szMelden = (wo, treffer) => { for (const t of treffer) if (!t.teil && t.wert && t.wert !== schrittAnzahl && !szOffen.some(o => o.wo === wo && o.wert === t.wert)) szOffen.push({ wo, wert: t.wert }); };
const szPruefen = (s, wo) => { if (typeof s === 'string' && schrittAnzahl >= 3) szMelden(wo, szTreffer(s)); };
const szSetzen = (s, wo) => {
  if (typeof s !== 'string' || schrittAnzahl < 3) return s;
  const treffer = szTreffer(s), t = treffer[0];
  if (treffer.length !== 1 || t.teil || !t.wert || t.wert === schrittAnzahl || (SZ_ANF.test(s.slice(0, t.start)) && SZ_ANF.test(s.slice(t.start + t.zahl.length)))) { szMelden(wo, treffer); return s; }
  // Umschrift ohne Umlaut nur, wenn das Modell selbst fuenf schrieb
  const wortNeu = t.zahl.toLowerCase() === 'fuenf' ? SZ_WORT[schrittAnzahl].replace('ü', 'ue') : SZ_WORT[schrittAnzahl];
  szAlt.push(t.zahl);
  if (!szOrte.includes(wo)) szOrte.push(wo);
  return s.slice(0, t.start) + (/^\d+$/.test(t.zahl) ? String(schrittAnzahl) : szFall(t.zahl, wortNeu)) + s.slice(t.start + t.zahl.length);
};
const p = Object.assign({}, pModell);
if (Array.isArray(pModell.slides)) p.slides = pModell.slides.map((f, i) => { if (!f || typeof f !== 'object') return f; const h = szSetzen(f.heading, i === 0 ? 'Titel' : 'Folienüberschrift'); szPruefen(f.text, 'Folientext'); return Object.assign({}, f, { heading: h }); });
p.thumbnail_hook = szSetzen(pModell.thumbnail_hook, 'Aufhänger');
// Einleitung, Bildunterschrift und LinkedIn bleiben wortgleich wie vom Modell (p traegt sie aus Object.assign), nur geprueft
if (pModell.intro && typeof pModell.intro === 'object' && !Array.isArray(pModell.intro)) { szPruefen(pModell.intro.heading, 'Einleitung'); szPruefen(pModell.intro.text, 'Einleitung'); }
szPruefen(pModell.caption_instagram, 'Bildunterschrift');
szPruefen(pModell.linkedin_post, 'LinkedIn');
const szOffenHinweis = Array.from(new Set(szOffen.map(o => o.wert))).map(w => 'Schrittzahl im Text (' + w + ') weicht vom Ablauf (' + schrittAnzahl + ') ab: ' + szOffen.filter(o => o.wert === w).map(o => o.wo).join(', ')).join('; ');
const szHinweis = szOrte.length ? 'Schrittzahl auf ' + schrittAnzahl + ' gesetzt wie die Schritte (Modell schrieb ' + szAlt.filter((v, i, a) => a.indexOf(v) === i).join(', ') + ') in ' + szOrte.join(', ') : '';
let folien = (Array.isArray(p.slides) ? p.slides : []).filter(f => f && (f.heading || f.text));
// Warum: G9 verlangt 5 bis 8 Folien. Zu viele werden gekuerzt (die Abschlussfolie bleibt), zu wenige sind ein Fehler.
// Warum zusammenlegen statt abschneiden: slice(0, 7) verwarf ab 9 Folien die Schritte 7 und folgende still.
// Jetzt bleibt die volle Liste als slides_all fuer Layout 4 erhalten; die 8er-Fassung fuer das alte Layout nennt die weiteren Titel in Folie 7.
// Warum leere Ueberschrift als Fund: eine Folie mit Text, aber ohne Ueberschrift, galt bisher als gesetzt; jetzt bekommt sie die ersten Worte des Textes und einen Vermerk.
const leerTitel = [];
folien = folien.map((f, i) => {
  const h = String(f.heading || '').replace(/\*/g, '').trim();
  if (h) return f;
  leerTitel.push(i + 1);
  const w = String(f.text || '').replace(/\*/g, '').trim().split(/\s+/).slice(0, 6).join(' ');
  return { ...f, heading: w || 'Ohne Titel' };
});
// Warum 70 bleibt: Regel 9 verlangt hoechstens 60 Zeichen, die Kuerzung greift erst ab 70; Layout 4 setzt 70 Zeichen bei 64 px noch in 4 Zeilen (22 Zeichen je Zeile).
const UEB_MAX = 70;
const langeUeb = folien.map((f, i) => ({ nr: i + 1, n: String(f.heading || '').trim().length, hart: ohneWortgrenze(f.heading, UEB_MAX) })).filter(x => x.n > UEB_MAX);
let folienAlle = null;
let zusammengelegt = 0;
if (folien.length > 8) {
  folienAlle = folien.slice();
  const rest = folien.slice(7, -1);
  zusammengelegt = rest.length;
  const f7 = folien[6];
  const zusatz = ' Dazu: ' + rest.map(f => kuerze(String(f.heading || '').replace(/^\s*(schritt|step)\s*\d+\s*[:.)–—-]?\s*/i, ''), 40)).filter(Boolean).join('; ') + '.';
  const eigen = Math.max(40, 258 - zusatz.length);
  folien = folien.slice(0, 6).concat([{ ...f7, text: kuerze(f7.text, eigen) + zusatz }], [folien[folien.length - 1]]);
}
// Warum Testschalter: 'pruefen' kuerzt hier auf 4 Folien, damit der Fehlerausgang dieses Knotens nachweisbar ist, Standard 'aus'.
if (cfg.test_truncate_slides === 'pruefen') folien = folien.slice(0, 4);
if (folien.length < 5) throw new Error('Paket hat nur ' + folien.length + ' Folien, verlangt sind 5 bis 8.');
folien = folien.map((f, i) => ({
  index: i + 1,
  type: i === 0 ? 'titel' : (i === folien.length - 1 ? 'abschluss' : 'inhalt'),
  heading: kuerzeWort(f.heading, UEB_MAX),
  text: kuerze(f.text, 260),
  cta: ''
}));
// Warum: die letzte Folie traegt immer die Handlungsaufforderung aus dem Kundenprofil, nicht die Formulierung des Modells.
folien[folien.length - 1].cta = kunde.cta_text || '';
// slides_all: dieselbe Normalisierung wie folien, aber ohne Zusammenlegen (nur wenn mehr als 8 Folien kamen).
const folienAlleNorm = folienAlle ? folienAlle.map((f, i) => ({ index: i + 1, type: i === 0 ? 'titel' : (i === folienAlle.length - 1 ? 'abschluss' : 'inhalt'), heading: kuerzeWort(f.heading, UEB_MAX), text: kuerze(f.text, 260), cta: i === folienAlle.length - 1 ? (kunde.cta_text || '') : '' })) : null;
// Warum: Hashtags ohne Leer- und Sonderzeichen, feste Marken-Hashtags zuerst, keine Doppelten.
const normTag = t => '#' + String(t || '').replace(/^#+/, '').replace(/[^A-Za-z0-9ÄÖÜäöüß_]/g, '');
// Warum (Paket 3, Hashtags doppelt): das Modell setzt Hashtags trotz Vorgabe teils auch in die Bildunterschrift. Sie werden dort herausgezogen und mit dem Feld hashtags zusammengefuehrt, damit jeder Tag nur einmal erscheint.
const capRoh = String(p.caption_instagram || '');
const tagMuster = /#(?=[\p{N}_]*\p{L})[\p{L}\p{N}_]+/gu;
const ausCaption = capRoh.match(tagMuster) || [];
const captionOhne = capRoh.replace(tagMuster, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();
// Warum Map mit toLowerCase: #KI und #ki sind derselbe Tag, die erste Schreibweise gewinnt, feste Marken-Hashtags stehen zuerst.
// Warum Laengengrenze je Tag (13.10.2026): die Anzahl war begrenzt, die Laenge nicht; 15 Tags zu 150 Zeichen ergaben 2.254 Zeichen und rissen die 2.200-Grenze.
// Ein Tag ueber 40 Zeichen (samt #) wird verworfen und in quality_notes vermerkt. 15 Tags belegen so hoechstens 15 x 40 + 14 = 614 Zeichen, das Budget bleibt immer positiv.
const TAG_MAX = 40;
const tagMap = new Map();
const tagZuLang = new Map();
for (const t of (kunde.hashtags_fest || []).concat(p.hashtags || [], ausCaption).map(normTag)) {
  if (t.length <= 1) continue;
  if (t.length > TAG_MAX) { tagZuLang.set(t.toLowerCase(), t); continue; }
  if (!tagMap.has(t.toLowerCase())) tagMap.set(t.toLowerCase(), t);
}
const tags = Array.from(tagMap.values()).slice(0, 15);
// Warum (12.10.2026): die Hashtags sollen aus echten aktuellen Posts kommen. Gibt es Vorlagen, muss mindestens ein Hashtag zu deren Hashtags oder Keywords passen, sonst Hinweis bei der Freigabe.
const research = (() => { try { const r = $('Recherche auswerten [Code]'); return r.isExecuted ? r.first().json : null; } catch (e) { return null; } })();
// Warum nur viral_hashtags (12.10.2026): die Sammelzeile KEYWORDS haengt an keinem einzelnen Post und ist kein Herkunftsnachweis; gezaehlt wird nur, was an einem belegten Post stand.
const vorlage = research && research.viral_status === 'ok' ? [].concat(research.viral_hashtags || []).join(' ').toLowerCase().replace(/[^\p{L}\p{N}_ ]/gu, ' ') : '';
// Warum exakt: ein Hashtag zaehlt nur, wenn genau er an einem belegten Post stand, keine Teilzeichenketten; der Unterstrich bleibt Teil des Hashtags (#ai_tools ist nicht #ai).
const vorlageSet = new Set(vorlage.split(' ').filter(Boolean));
const tagTreffer = tags.filter(t => vorlageSet.has(t.slice(1).toLowerCase()));
// Warum Pruefung im Code (12.10.2026, Beitragsqualitaet, Lauf 697): Links, fehlende Werkzeugnamen und Zahlen ohne Beleg werden deterministisch gefunden und bei der Freigabe angezeigt, statt dem Modell zu vertrauen.
const ohneLink = s => String(s || '').replace(/(https?:\/\/|www\.)\S+/gi, '').replace(/[ \t]{2,}/g, ' ').trim();
const quality = [];
if (tagZuLang.size) quality.push(tagZuLang.size + ' Hashtag(s) über ' + TAG_MAX + ' Zeichen verworfen: ' + Array.from(tagZuLang.values()).map(t => kuerze(t, 25)).join(', '));
// Warum Hinweis: eine gekuerzte Ueberschrift verliert ihr Ende, Patrick soll das vor der Freigabe sehen; Zahl in Klammern ist die Laenge vor der Kuerzung.
// Warum zwei Hinweise: der Hinweis behauptete auch bei harter Kuerzung eine Wortgrenze; jetzt passt er zur Kuerzungsart.
const langeWeich = langeUeb.filter(x => !x.hart), langeHart = langeUeb.filter(x => x.hart);
if (langeWeich.length) quality.push('Überschrift über ' + UEB_MAX + ' Zeichen an Wortgrenze gekürzt: ' + langeWeich.map(x => 'Folie ' + x.nr + ' (' + x.n + ')').join(', '));
if (langeHart.length) quality.push('Überschrift über ' + UEB_MAX + ' Zeichen ohne Wortgrenze mitten im Wort gekürzt: ' + langeHart.map(x => 'Folie ' + x.nr + ' (' + x.n + ')').join(', '));
const linkDa = /(https?:\/\/|www\.)\S+/i;
if (linkDa.test(captionOhne) || folien.some(f => linkDa.test(f.text) || linkDa.test(f.heading))) quality.push('Link entfernt (Instagram verlinkt im Beitrag nicht)');
folien = folien.map(f => ({...f, heading: ohneLink(f.heading), text: ohneLink(f.text)}));
// Warum intro (17.10.2026, Probelauf 1164): Layout 4 setzte als Einleitung das Thema, das Modell hatte es woertlich als Titel uebernommen,
// Folie 1 und 2 trugen dieselbe Ueberschrift. Das Modell liefert jetzt eine eigene Einleitung (Patrick 17.10.2026, "Modell-Einleitung").
// Fehlt sie oder ist die Ueberschrift leer, ist intro null; Layout 4 setzt dann selbst einen Ersatz. Grenzen 70 und 200 wie Folien mit Reserve.
const introRoh = p.intro && typeof p.intro === 'object' && !Array.isArray(p.intro) ? p.intro : null;
const introH = introRoh ? kuerzeWort(ohneLink(String(introRoh.heading || '').replace(/[*]/g, '')), UEB_MAX) : '';
const intro = introH ? { heading: introH, text: kuerze(ohneLink(String(introRoh.text || '').replace(/[*]/g, '')), 200) } : null;
if (introRoh && (linkDa.test(String(introRoh.heading || '')) || linkDa.test(String(introRoh.text || ''))) && !quality.includes('Link entfernt (Instagram verlinkt im Beitrag nicht)')) quality.push('Link entfernt (Instagram verlinkt im Beitrag nicht)');
// Warum Kommentar-Frage (19.10.2026, Lauf 1181, Patrick: dass die Leute kommentieren, aber nicht immer derselbe Satz): Layout 4 setzte auf jede Schlussfolie
// Welcher Schritt zuerst? Das Modell liefert jetzt comment_question (Regel 19). Gueltig ist sie mit hoechstens 40 Zeichen; ein fehlendes Fragezeichen wird ergaenzt.
// Fehlt sie oder ist sie zu lang, ist comment_question null und Layout 4 nimmt eine vorbereitete Frage. Ob sie der Frage des letzten Laufs gleicht, ist hier nicht pruefbar
// (kein Speicherfeld dafuer); die Abwechslung kommt aus dem Modell und aus der Zufallswahl in Layout 4.
const KQ_MAX = 40;
let kqText = ohneLink(String(p.comment_question || '').replace(/[*#]/g, '')).replace(/\s+/g, ' ').trim();
if (kqText && !/\?$/.test(kqText)) kqText = kqText.replace(/[.!:;,]+$/, '') + '?';
const commentQuestion = kqText && kqText.length <= KQ_MAX ? kqText : null;
const kqHinweis = kqText && !commentQuestion ? 'Kommentar-Frage über ' + KQ_MAX + ' Zeichen (' + kqText.length + '), Schlussfolie nimmt eine vorbereitete Frage' : '';
// Warum Aufhaenger (19.10.2026, Laeufe 1181 und 1183, Patrick: Folie 1 soll wie ein Thumbnail wirken): das Modell liefert thumbnail_hook (Regel 20), Layout 4 setzt ihn
// gross auf Folie 1 und die Titelueberschrift klein darunter. Gueltig mit hoechstens 6 Woertern und 50 Zeichen (Regel 20 verlangt 40, Reserve wie bei UEB_MAX).
// Fehlt er, ist er zu lang oder gleicht er der Titelueberschrift, ist thumbnail_hook null und Folie 1 zeigt wie bisher die Titelueberschrift.
const HOOK_WOERTER = 6, HOOK_MAX = 50;
const hookText = ohneLink(String(p.thumbnail_hook || '').replace(/[*#]/g, '')).replace(/\s+/g, ' ').trim().replace(/[.,;:!]+$/, '');
const hookWoerter = hookText ? hookText.split(' ').length : 0;
const hookNorm = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const hookGleich = !!hookText && hookNorm(hookText) === hookNorm((folien[0] || {}).heading);
