// ---------- Teil 1: Fakten (nur wenn Recherche Sonar lief) ----------
let fakt = { research_status: 'uebersprungen', research_text: '', research_sources: [], research_model: 'perplexity/sonar', research_tokens: null, research_fact_cost_usd: null, research_note: '', coverage_gaps: [], research_fact_count: 0, research_fact_total: 0, research_truncated: false, research_facts_shortened: 0, research_facts_dropped: 0, coverage_gap_total: 0 };
if (lief('Recherche Sonar [HTTP Request]')) {
  const r = ($input.first() || {}).json || {};
  const wahl = (Array.isArray(r.choices) ? r.choices : [])[0] || {};
  const msg = wahl.message || {};
  // Warum Abdeckungsluecken getrennt (19.10.2026, Lauf 1160): Sonar meldet einen verlangten Teilaspekt ohne Beleg als Zeile ABDECKUNGSLÜCKE: <Teilaspekt>.
  // Diese Zeilen sind kein Fakt: sie fallen aus research_text und aus der Adresssuche, zaehlen nicht in research_fact_count und gehen als coverage_gaps bis zur Freigabe (Paket pruefen, quality_notes).
