  // Gruppe 1 ist der Teilaspekt in Klammern, Gruppe 2 der Text nach dem Doppelpunkt; ist der Text leer, gilt der Klammerinhalt als Name der Luecke.
  const LUECKE = /^\s*(?:(?:[-*•]|\d+[.)])\s*)?\**\s*(?:\[([^\]\n]*)\]\s*)?\**\s*ABDECKUNGSL(?:Ü|UE|U)CKE\s*\**\s*:\s*(.*)$/i;
  const roh = String(msg.content || '').trim();
  // Warum Entdoppelung vor der Kuerzung: die Namen wurden auf 80 Zeichen gekuerzt und erst danach entdoppelt; 7 verschiedene Luecken
  // mit gleichen ersten 80 Zeichen zaehlten als 1. Jetzt zaehlt der volle, getrimmte Name in Kleinschreibung (erste Schreibweise gewinnt), gekuerzt wird nur fuer die Anzeige.
  const lueckenMap = new Map();
