  // Der Schreibprompt waechst dadurch um hoechstens 1.000 Zeichen (rund 250 Tokens); mit voller Recherche und vollen Vorlagen hat er 12.887 Zeichen (gemessen 19.10.2026), die Ausgabegrenze von 3.000 Tokens bleibt unberuehrt.
  const RECHERCHE_MAX = 3500;
  const ohneMarken = text.replace(/\[(\d+)\]/g, '');
  const faktZeilen = s => s.split('\n').filter(z => /^\s*(?:[-*•]|\d+[.)])\s+\S/.test(z)).length;
