  // Faktzeilen ohne Adresse bleiben im Text (Prompt unveraendert), zaehlen nicht und meldet Paket pruefen in quality_notes.
  fakt.research_fact_count = fakt.research_text ? fakt.research_text.split('\n').filter(z => istFakt(z) && /https?:\/\//i.test(z)).length : 0;
