const KOMMENTAR_FRAGEN = ['Was probierst du als Erstes aus?', 'Welcher Punkt hilft dir am meisten?', 'Was würdest du noch ergänzen?', 'Wie löst du das bisher?', 'Was hält dich noch davon ab?', 'Welche Erfahrung hast du damit?', 'Was davon nutzt du schon?', 'Wo hakt es bei dir am meisten?', 'Was überrascht dich hier am meisten?', 'Womit fängst du diese Woche an?'];
