const kommentarFrageFest = KOMMENTAR_FRAGEN[Math.floor(kommentarZufall() * KOMMENTAR_FRAGEN.length)];
const kommentarAuf = '*' + KOMMENTAR_AUF[Math.floor(kommentarZufall() * KOMMENTAR_AUF.length)] + '*';
const schlussFrage = frage => { const t = titelSetzen(frage, 920, 96, 48, 2, false, 48); return t.ok ? { typ: 'schluss', titel: markiere(t.zeilen), groesse: t.px, text: kommentarAuf, _unten: 1100, _breit: true } : null; };
const schlussV2 = () => {
