  const start = KOMMENTAR_FRAGEN.indexOf(kommentarFrageFest);
  for (let i = 0; i < KOMMENTAR_FRAGEN.length; i++) { const s = schlussFrage(KOMMENTAR_FRAGEN[(start + i) % KOMMENTAR_FRAGEN.length]); if (s) return s; }
