const farbenV2 = Object.assign({}, farben);
if (hex(farben.grund_1) && hex(farben.grund_2) && Math.min(kontrast(farben.primaer, farben.grund_1), kontrast(farben.primaer, farben.grund_2)) < 1.6)
  farbenV2.primaer = '#' + [1, 3, 5].map(i => Math.round(parseInt(akzent.substr(i, 2), 16) * 0.68).toString(16).padStart(2, '0')).join('');
function planV2(grenze) {
  const S = v2Schritte.length;
  if (S < 3) return nb('v2-schritte:' + S);
