  box-shadow:0 0 0 6px rgba(0,0,0,.6), 0 24px 60px rgba(0,0,0,.6), 0 0 100px var(--akzent-35);display:flex;align-items:center;justify-content:center;overflow:hidden}
.bildmarke img{display:block;width:180px;height:auto}
.bildmarke span{font-family:var(--font-titel);font-weight:700;font-size:40px;text-transform:uppercase;color:var(--text)}
/* Seit 19.10.2026: Bildelement der Titelfolie, KI-Bild im Rahmen in Farbe oder grosses Themensymbol im Medaillon */
.titelbild img{filter:contrast(1.06) saturate(.92)}
.titelsymbol{position:absolute;right:var(--rand);border-radius:50%;border:10px solid var(--akzent);padding:6%;
  background:radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--grund-1) 80%, white), var(--grund-1) 75%);
  box-shadow:0 0 0 6px rgba(0,0,0,.6), 0 24px 60px rgba(0,0,0,.6), 0 0 120px var(--akzent-35)}
.titelsymbol svg{display:block;width:100%;height:100%}

/* Bruecke */
.bruecke .frage{font-family:var(--font-titel);font-weight:700;text-transform:uppercase;font-size:88px;line-height:var(--zeile-titel);color:var(--text-gedimmt);text-shadow:6px 6px 0 var(--schatten);margin-bottom:36px}
.bruecke .frage .a{color:var(--akzent)}

/* Schritt */
.schritt .titel{font-size:96px;margin-bottom:40px}
.schritt .ziffer{position:absolute;right:50px;top:150px;font-family:var(--font-titel);font-weight:700;font-size:720px;line-height:1;color:var(--primaer);opacity:.55}
.schritt .nummer{display:inline-block;font-family:var(--font-titel);font-weight:700;font-size:44px;line-height:1;color:var(--grund-2);background:var(--akzent);padding:12px 18px 10px;margin-bottom:28px;box-shadow:6px 6px 0 var(--schatten)}
.schritt .ziffer-umriss{position:absolute;right:40px;bottom:150px;font-family:var(--font-titel);font-weight:700;font-size:560px;line-height:1;color:transparent;-webkit-text-stroke:5px var(--akzent);opacity:.8}

/* Speichern */
.speichern .block{right:var(--rand);text-align:center}
.speichern .titel{font-size:176px;margin-bottom:46px}
.speichern svg{display:block;margin:0 auto 44px}
.speichern .fliess{max-width:800px;margin:0 auto}

/* Zusammenfassung */
.zusammen .titel{font-size:110px;margin-bottom:40px}
.zusammen ol{list-style:none}
.zusammen li{display:flex;gap:26px;align-items:baseline;font-weight:700;font-size:38px;line-height:1.25;margin-bottom:16px;color:var(--text);text-shadow:3px 3px 0 rgba(0,0,0,.45);overflow-wrap:anywhere}
.zusammen li b{font-family:var(--font-titel);font-weight:700;font-size:52px;color:var(--akzent);width:34px;flex:none}

/* Schluss */
.schluss .medaillon{position:absolute;left:290px;top:180px;width:500px;height:500px;border-radius:50%;
  border:12px solid var(--akzent);background:radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--grund-1) 80%, white), var(--grund-1) 75%);
  box-shadow:0 0 0 6px rgba(0,0,0,.6), 0 30px 80px rgba(0,0,0,.6), 0 0 120px var(--akzent-35);
  display:flex;flex-direction:column;align-items:center;justify-content:center}
.schluss .medaillon img{display:block;width:380px;height:auto}
.schluss .medaillon .linie{width:160px;height:6px;background:var(--akzent);margin:14px 0 18px}
.schluss .medaillon .unterzeile{font-weight:600;font-size:24px;letter-spacing:.2em;color:var(--akzent);text-transform:uppercase}
.schluss .block{right:var(--rand);text-align:center}
.schluss .titel{font-size:96px;margin-bottom:28px}

/* ---------- Ebene 9: Folienelemente (je Folie, nie ueber eine Kante) ---------- */
.swipe{position:absolute;right:var(--rand);top:72px;display:flex;align-items:center;gap:14px;color:var(--akzent);font-weight:700;font-size:24px;letter-spacing:.16em}
.swipe path{stroke:var(--akzent)}
/* auf Vollbild-Fotos bekommt der Wisch-Hinweis eine dunkle Unterlage (Kontrast) */
.swipe.auf-foto{background:var(--grund-1);padding:10px 16px 10px 20px;margin-right:-20px;margin-top:-10px;box-shadow:6px 6px 0 var(--schatten)}
.seite{position:absolute;right:var(--rand);bottom:64px;width:60px;height:60px;border-radius:50%;border:3px solid var(--akzent);background:color-mix(in srgb, var(--grund-1) 70%, transparent);
  display:flex;align-items:center;justify-content:center;font-weight:700;font-size:24px;color:var(--text)}
.fortschritt{position:absolute;left:var(--rand);bottom:84px;display:flex;gap:10px}
.fortschritt span{width:0;height:0;border-top:10px solid transparent;border-bottom:10px solid transparent;border-left:16px solid var(--akzent-35)}
.fortschritt span.an{border-left-color:var(--akzent)}

/* Pruefansicht ?ohnetext=1: Text unsichtbar, Grund und Fotos bleiben (Kontrastmessung) */
body.ohnetext .folie, body.ohnetext .folie *, body.ohnetext #elemente *{color:transparent !important;text-shadow:none !important;-webkit-text-stroke:0 !important}
body.ohnetext .schluss .medaillon, body.ohnetext .bildmarke, body.ohnetext .titelsymbol, body.ohnetext .kante, body.ohnetext .speichern svg{visibility:hidden}
body.ohnetext .schritt .nummer{visibility:hidden}
section.folie[data-tg] .titel, section.folie[data-tg] .frage{font-size:var(--tg) !important}
</style>
